pub async fn approve_variation_with_boq(path:&Path,r:ApprovalRequest)->std::result::Result<Result,String>{
 if r.operation_id.trim().is_empty()||r.actor.trim().is_empty()||r.approved_at.trim().is_empty(){return Err("Variation approval requires operation ID, actor and date.".into())}
 let mut tx=db(path).await?.begin().await.map_err(|e|e.to_string())?;guard(&mut tx,&r.operation_id,true).await?;
 let outcome=async{
  let(scope,mut variation)=scope_doc(&mut tx,"variations",&r.source_id).await?;
  if s(&variation,"status")!="Submitted"{return Err("Only a submitted variation can be approved.".into())}
  let contract_id=scope.contract_id.as_deref().ok_or("Variation requires a contract.")?;
  let parent:Option<String>=sqlx::query_scalar("SELECT parent_main_contract_id FROM contracts WHERE id=?").bind(contract_id).fetch_optional(&mut *tx).await.map_err(|e|e.to_string())?.ok_or("Variation contract was not found.")?;
  let rows=sqlx::query("SELECT payload FROM variation_lines WHERE json_extract(payload,'$.variation_id')=?").bind(&r.source_id).fetch_all(&mut *tx).await.map_err(|e|e.to_string())?;
  if rows.is_empty(){return Err("A variation requires at least one line before approval.".into())}
  let mut total=0.0;for row in rows{let line:Value=serde_json::from_str(&row.try_get::<String,_>("payload").map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;total+=n(&line,"value_impact")};let total=money(total);
  let snapshot=variation.clone();let o=variation.as_object_mut().ok_or("Invalid variation payload.")?;o.insert("status".into(),json!("Approved"));o.insert("cost_impact".into(),json!(total));o.insert("approved_by".into(),json!(r.actor));o.insert("approved_date".into(),json!(r.approved_at));o.insert("baseline_revision_status".into(),json!("Pending"));o.insert("baseline_revision_required".into(),json!(true));put(&mut tx,"variations",&r.source_id,&variation).await?;
  let affected=materialize_variation_boq(&mut tx,&scope,&r.source_id,&variation,&r.approved_at).await?;
  recompute_contract_time_impact(&mut tx,contract_id).await?;
  let cash_id=format!("variation_cash_forecast:{}",r.source_id);sqlx::query("DELETE FROM cash_flow WHERE json_extract(payload,'$.source_type')='variation_cash_forecast' AND json_extract(payload,'$.source_id')=?").bind(&r.source_id).execute(&mut *tx).await.map_err(|e|e.to_string())?;
  if total.abs()>0.000001{let subcontract=parent.is_some();let(inflow,outflow,net)=if subcontract{(money((-total).max(0.0)),money(total.max(0.0)),money(-total))}else{(money(total.max(0.0)),money((-total).max(0.0)),money(total))};let payload=json!({"id":cash_id,"date":r.approved_at,"description":format!("Approved variation forecast: {}",s(&variation,"variation_number")),"category":"Commercial Variation","inflow":inflow,"outflow":outflow,"net":net,"cumulative_balance":0,"movement_type":"Forecast","status":"Open","source_type":"variation_cash_forecast","source_id":r.source_id});sqlx::query("INSERT INTO cash_flow(id,created_at,project_id,contract_id,boq_header_id,boq_item_id,parent_main_project_id,parent_main_contract_id,payload) VALUES (?,?,?,?,?,?,?,?,?)").bind(&cash_id).bind(stamp()).bind(&scope.project_id).bind(&scope.contract_id).bind(&scope.boq_header_id).bind(&scope.boq_item_id).bind(&scope.parent_main_project_id).bind(&scope.parent_main_contract_id).bind(payload.to_string()).execute(&mut *tx).await.map_err(|e|e.to_string())?;}
  for boq in affected{let ids=sqlx::query("SELECT id FROM contract_sov_lines WHERE contract_id=? AND boq_item_id=?").bind(contract_id).bind(&boq).fetch_all(&mut *tx).await.map_err(|e|e.to_string())?;for row in ids{recompute_sov(&mut tx,&row.try_get::<String,_>("id").map_err(|e|e.to_string())?).await?}}
  post(&mut tx,&r.operation_id,"variations",&r.source_id,"VariationApproval",&r.actor,&r.approved_at,"Approved variation",&snapshot).await
 }.await;
 match outcome{Ok(())=>{guard(&mut tx,&r.operation_id,false).await?;tx.commit().await.map_err(|e|e.to_string())?;Ok(Result{operation_id:r.operation_id,status:"Posted".into()})},Err(e)=>{tx.rollback().await.map_err(|x|x.to_string())?;Err(e)}}
}
pub async fn approve_payment_certificate(path:&Path,r:ApprovalRequest)->std::result::Result<Result,String>{
 if r.operation_id.trim().is_empty()||r.actor.trim().is_empty()||r.approved_at.trim().is_empty(){return Err("Certificate approval requires operation ID, actor and date.".into())}
 let mut tx=db(path).await?.begin().await.map_err(|e|e.to_string())?;guard(&mut tx,&r.operation_id,true).await?;
 let outcome=async{
  let(scope,mut v)=scope_doc(&mut tx,"payment_certificates",&r.source_id).await?;
  if s(&v,"status")!="Submitted"{return Err("Only a submitted payment certificate can be approved.".into())}
  if !matches!(s(&v,"certificate_type").as_str(),"Client"|"Subcontractor"){return Err("Certificate type must be Client or Subcontractor.".into())}
  if n(&v,"gross_certified_value")<=0.0{return Err("Payment certificate gross value must be greater than zero.".into())}
  let gross=n(&v,"gross_certified_value");let retention=money(gross*n(&v,"retention_rate")/100.0);let taxable=money(gross-retention-n(&v,"advance_recovery")-n(&v,"deductions"));
  if taxable < -0.000001{return Err("Retention, advance recovery and deductions cannot exceed gross certified value.".into())}
  let(cumulative_retention,remaining_advance)=certificate_balances(&mut tx,&scope,&r.source_id,&v).await?;
  let tax=money(taxable.max(0.0)*n(&v,"tax_rate")/100.0);let net=money(taxable+tax);let day=if s(&v,"certificate_date").is_empty(){r.approved_at.clone()}else{s(&v,"certificate_date")};let client=s(&v,"certificate_type")=="Client";
  let o=v.as_object_mut().ok_or("Invalid certificate payload.")?;
  for(k,value)in[("retention_amount",retention),("cumulative_retention_amount",cumulative_retention),("remaining_advance_balance",remaining_advance),("taxable_amount",taxable),("tax_amount",tax),("net_certified_value",net)]{o.insert(k.into(),json!(value));}
  o.insert("status".into(),json!("Approved"));o.insert("approved_by".into(),json!(r.actor));o.insert("approved_date".into(),json!(r.approved_at));
  put(&mut tx,"payment_certificates",&r.source_id,&v).await?;synchronize_invoice_tracking(&mut tx,&v,None,false).await?;cash(&mut tx,&scope,&r.source_id,&day,&s(&v,"certificate_number"),"Forecast","Open",net,client).await?;post(&mut tx,&r.operation_id,"payment_certificates",&r.source_id,"PaymentCertificateApproval",&r.actor,&r.approved_at,"Approved payment certificate",&v).await
 }.await;
 match outcome{Ok(())=>{guard(&mut tx,&r.operation_id,false).await?;tx.commit().await.map_err(|e|e.to_string())?;Ok(Result{operation_id:r.operation_id,status:"Posted".into()})},Err(e)=>{tx.rollback().await.map_err(|x|x.to_string())?;Err(e)}}
}
pub async fn settle_payment_certificate(path:&Path,r:CertificateSettlementRequest)->std::result::Result<Result,String>{
 if r.operation_id.trim().is_empty()||r.actor.trim().is_empty()||r.paid_at.trim().is_empty(){return Err("Certificate settlement requires operation ID, actor and payment date.".into())}
 let mut tx=db(path).await?.begin().await.map_err(|e|e.to_string())?;guard(&mut tx,&r.operation_id,true).await?;
 let outcome=async{
  let(scope,mut v)=scope_doc(&mut tx,"payment_certificates",&r.certificate_id).await?;
  let current_status=s(&v,"status");
  if !matches!(current_status.as_str(),"Approved"|"Partially Paid"){return Err("Only an approved or partially paid payment certificate can be settled.".into())}
  let net=n(&v,"net_certified_value");
  if net<=0.0{return Err("Approved certificate has no governed net value.".into())}
  let prior_paid=n(&v,"paid_amount");
  let settle_amount=match r.payment_amount{Some(amt) if amt>0.0=>money(amt),_=>money(net-prior_paid)};
  if settle_amount<=0.0{return Err("Payment amount must be greater than zero.".into())}
  let total_paid=money(prior_paid+settle_amount);
  if total_paid>net+0.000001{return Err("Cumulative payment cannot exceed the net certified value.".into())}
  let is_fully_paid=total_paid>=net-0.000001;
  let next_status=if is_fully_paid{"Paid"}else{"Partially Paid"};
  let client=s(&v,"certificate_type")=="Client";
  let o=v.as_object_mut().ok_or("Invalid certificate payload.")?;
  o.insert("status".into(),json!(next_status));
  o.insert("payment_date".into(),json!(r.paid_at));
  o.insert("paid_by".into(),json!(r.actor));
  o.insert("paid_amount".into(),json!(total_paid));
  o.insert("balance_due".into(),json!(money((net-total_paid).max(0.0))));
  put(&mut tx,"payment_certificates",&r.certificate_id,&v).await?;
  let tracking_status=if is_fully_paid{Some(r.paid_at.as_str())}else{None};
  synchronize_invoice_tracking(&mut tx,&v,tracking_status,false).await?;
  cash(&mut tx,&scope,&r.certificate_id,&r.paid_at,&s(&v,"certificate_number"),"Actual",if is_fully_paid{"Settled"}else{"Partially Settled"},total_paid,client).await?;
  post(&mut tx,&r.operation_id,"payment_certificates",&r.certificate_id,"PaymentCertificateSettlement",&r.actor,&r.paid_at,"Settled payment certificate",&v).await
 }.await;
 match outcome{Ok(())=>{guard(&mut tx,&r.operation_id,false).await?;tx.commit().await.map_err(|e|e.to_string())?;Ok(Result{operation_id:r.operation_id,status:"Posted".into()})},Err(e)=>{tx.rollback().await.map_err(|x|x.to_string())?;Err(e)}}
}
pub async fn reverse_commercial_posting(path:&Path,r:ReversalRequest)->std::result::Result<Result,String>{if !matches!(r.source_table.as_str(),"cost_changes"|"payment_certificates")||r.operation_id.trim().is_empty()||r.actor.trim().is_empty()||r.reason.trim().is_empty(){return Err("Commercial reversal requires source, operation ID, actor and reason.".into())}let mut tx=db(path).await?.begin().await.map_err(|e|e.to_string())?;guard(&mut tx,&r.operation_id,true).await?;let outcome=async{let(scope,mut v)=scope_doc(&mut tx,&r.source_table,&r.source_id).await?;if !matches!(s(&v,"status").as_str(),"Approved"|"Partially Paid"|"Paid"){return Err("Only an approved, partially paid or paid commercial document can be reversed.".into())}let snapshot=v.clone();let sov=s(&v,"contract_sov_line_id");let o=v.as_object_mut().ok_or("Invalid commercial payload.")?;o.insert("status".into(),json!("Reversed"));o.insert("reversed_by".into(),json!(r.actor));o.insert("reversal_reason".into(),json!(r.reason));put(&mut tx,&r.source_table,&r.source_id,&v).await?;if r.source_table=="payment_certificates"{synchronize_invoice_tracking(&mut tx,&v,None,true).await?;cash(&mut tx,&scope,&r.source_id,"",&s(&v,"certificate_number"),"Reversed","Reversed",0.0,false).await?;}else{recompute_sov(&mut tx,&sov).await?;}post(&mut tx,&r.operation_id,&r.source_table,&r.source_id,"CommercialReversal",&r.actor,&stamp(),&r.reason,&snapshot).await}.await;match outcome{Ok(())=>{guard(&mut tx,&r.operation_id,false).await?;tx.commit().await.map_err(|e|e.to_string())?;Ok(Result{operation_id:r.operation_id,status:"Posted".into()})},Err(e)=>{tx.rollback().await.map_err(|x|x.to_string())?;Err(e)}}}

pub async fn reverse_variation(path:&Path,r:ReversalRequest)->std::result::Result<Result,String>{
 if r.operation_id.trim().is_empty()||r.actor.trim().is_empty()||r.reason.trim().is_empty(){return Err("Variation reversal requires operation ID, actor and reason.".into())}
 let mut tx=db(path).await?.begin().await.map_err(|e|e.to_string())?;guard(&mut tx,&r.operation_id,true).await?;
 let outcome=async{
  let(scope,mut variation)=scope_doc(&mut tx,"variations",&r.source_id).await?;if s(&variation,"status")!="Approved"{return Err("Only an approved variation can be reversed.".into())};let contract_id=scope.contract_id.as_deref().ok_or("Variation requires a contract.")?;let snapshot=variation.clone();
  let rows=sqlx::query("SELECT id,boq_item_id,payload FROM variation_lines WHERE json_extract(payload,'$.variation_id')=?").bind(&r.source_id).fetch_all(&mut *tx).await.map_err(|e|e.to_string())?;let mut affected=Vec::new();
  for row in rows {let id:String=row.try_get("id").map_err(|e|e.to_string())?;let boq:Option<String>=row.try_get("boq_item_id").map_err(|e|e.to_string())?;let mut line:Value=serde_json::from_str(&row.try_get::<String,_>("payload").map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;if s(&line,"change_type")!="New Item"{if let Some(ref item)=boq{affected.push(item.clone())}}let obj=line.as_object_mut().ok_or("Invalid variation-line payload.")?;obj.remove("applied_at");obj.remove("effective_date");let target=line.get("boq_item_id").and_then(Value::as_str).map(str::to_string);sqlx::query("UPDATE variation_lines SET boq_item_id=?,payload=? WHERE id=?").bind(target).bind(line.to_string()).bind(&id).execute(&mut *tx).await.map_err(|e|e.to_string())?;}
  let prefix=format!("boq:variation:{}:%",r.source_id);let sov_prefix=format!("sov:variation:{}:%",r.source_id);sqlx::query("UPDATE contract_sov_lines SET payload=json_set(payload,'$.status','Reversed','$.reversed_by',?) WHERE id LIKE ?").bind(&r.actor).bind(&sov_prefix).execute(&mut *tx).await.map_err(|e|e.to_string())?;sqlx::query("UPDATE boq_items SET payload=json_set(payload,'$.status','Reversed','$.reversed_by',?) WHERE id LIKE ?").bind(&r.actor).bind(&prefix).execute(&mut *tx).await.map_err(|e|e.to_string())?;sqlx::query("UPDATE cash_flow SET payload=json_set(payload,'$.status','Reversed','$.movement_type','Reversed') WHERE json_extract(payload,'$.source_type')='variation_cash_forecast' AND json_extract(payload,'$.source_id')=?").bind(&r.source_id).execute(&mut *tx).await.map_err(|e|e.to_string())?;
  let o=variation.as_object_mut().ok_or("Invalid variation payload.")?;o.insert("status".into(),json!("Reversed"));o.insert("reversed_by".into(),json!(r.actor));o.insert("reversal_reason".into(),json!(r.reason));put(&mut tx,"variations",&r.source_id,&variation).await?;
  recompute_contract_time_impact(&mut tx,contract_id).await?;
  for boq in affected{let ids=sqlx::query("SELECT id FROM contract_sov_lines WHERE contract_id=? AND boq_item_id=?").bind(contract_id).bind(&boq).fetch_all(&mut *tx).await.map_err(|e|e.to_string())?;for row in ids{recompute_sov(&mut tx,&row.try_get::<String,_>("id").map_err(|e|e.to_string())?).await?}}
  post(&mut tx,&r.operation_id,"variations",&r.source_id,"VariationReversal",&r.actor,&stamp(),&r.reason,&snapshot).await
 }.await;match outcome{Ok(())=>{guard(&mut tx,&r.operation_id,false).await?;tx.commit().await.map_err(|e|e.to_string())?;Ok(Result{operation_id:r.operation_id,status:"Posted".into()})},Err(e)=>{tx.rollback().await.map_err(|x|x.to_string())?;Err(e)}}
}

